CADDY_NETWORK_RELAY_SOURCE_BUNDLE
printf '%s  %s\n' '9ebe1a7d6d8b57e6df07d1e84cca2b86fdf09fbc9345441c235e1805c7417793' "$bundle_dir/source.tar.gz" | sha256sum --check --status
